import dspy
from dspy.utils.dummies import DummyLM


class ToolAwareSignature(dspy.Signature):
    question: str = dspy.InputField()
    tools: list[dspy.Tool] = dspy.InputField()
    answer: str = dspy.OutputField()
    tool_calls: dspy.ToolCalls = dspy.OutputField()


def get_weather(city: str) -> str:
    return f"The weather in {city} is sunny"


class SpyLM(DummyLM):
    def __init__(self):
        super().__init__(
            [{"answer": "sunny", "tool_calls": {"tool_calls": []}}],
            adapter=dspy.JSONAdapter(),
        )
        self.response_formats = []

    @property
    def supported_params(self):
        return {"response_format"}

    @property
    def supports_response_schema(self):
        return True

    def forward(self, prompt=None, messages=None, **kwargs):
        self.response_formats.append(kwargs.get("response_format"))
        return super().forward(prompt=prompt, messages=messages, **kwargs)


lm = SpyLM()
adapter = dspy.JSONAdapter(use_native_function_calling=False)
program = dspy.Predict(ToolAwareSignature)

with dspy.context(lm=lm, adapter=adapter):
    result = program(question="What is the weather in Tokyo?", tools=[dspy.Tool(get_weather)])

assert lm.response_formats[0] == {"type": "json_object"}
assert result.answer == "sunny"
assert result.tool_calls == dspy.ToolCalls(tool_calls=[])
print("response_format:", lm.response_formats[0])
print("parsed_result:", {"answer": result.answer, "tool_calls": result.tool_calls.model_dump()})
