import dspy
from dspy.dsp.utils.utils import dotdict
from dspy.utils.dummies import DummyLM


class ToolSignature(dspy.Signature):
    question: str = dspy.InputField()
    tools: list[dspy.Tool] = dspy.InputField()
    answer: str = dspy.OutputField()
    tool_calls: dspy.ToolCalls = dspy.OutputField()


def get_weather(city: str) -> str:
    return f"The weather in {city} is sunny"


class ToolCallLM(DummyLM):
    def __init__(self):
        super().__init__([{}])
        self.last_kwargs = None

    @property
    def supports_function_calling(self):
        return True

    def forward(self, prompt=None, messages=None, **kwargs):
        self.last_kwargs = dict(kwargs)
        choice = dotdict(
            message=dotdict(
                content=None,
                tool_calls=[
                    {
                        "function": {
                            "name": "get_weather",
                            "arguments": '{"city": "Paris"}',
                        }
                    }
                ],
            ),
            finish_reason="tool_calls",
        )
        return dotdict(
            choices=[choice],
            usage=dotdict(prompt_tokens=0, completion_tokens=0, total_tokens=0),
            model="dummy",
        )


lm = ToolCallLM()
adapter = dspy.JSONAdapter(use_native_function_calling=True)
result = adapter(
    lm,
    {},
    ToolSignature,
    [],
    {"question": "What is the weather in Paris?", "tools": [dspy.Tool(get_weather)]},
)

parsed = result[0]
expected_tool_calls = dspy.ToolCalls(
    tool_calls=[dspy.ToolCalls.ToolCall(name="get_weather", args={"city": "Paris"})]
)
assert parsed["answer"] is None
assert parsed["tool_calls"] == expected_tool_calls
assert lm.last_kwargs["tools"][0]["function"]["name"] == "get_weather"
print("request_tools:", lm.last_kwargs["tools"])
print("parsed_tool_calls:", parsed["tool_calls"].model_dump())
print("parsed_answer:", parsed["answer"])
